select s.id, s.cat_id as productCategory_id, s.name, s.price, s.status, s.descr as description, s.img as image, s.create_time, s.update_time, s.create_uid as create_user, s.update_uid as update_user, c.name productCategoryName from pack s left join cat c on s.cat_id = c.id
and s.name like concat('%',#{name},'%')
and s.status = #{status}
and s.cat_id = #{categoryId}
order by s.create_time desc

select id, cat_id as productCategory_id, name, price, status, descr as description, img as image, create_time, update_time, create_uid as create_user, update_uid as update_user from pack
and name like concat('%',#{name},'%')
and cat_id = #{categoryId}
and status = #{status}

select count(id) from pack


        and status = #{status}


